<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Teacher','Admin']); render_header('Students'); ?><div class="page-title"><div><h1>Students</h1><p>View enrolled students.</p></div></div><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>ID Number</th><th>Name</th><th>Course</th><th>Year</th><th>Section</th><th>Status</th></tr></thead><tbody><?php foreach(rows('SELECT s.*,u.full_name,c.code AS course,sec.name AS section_name FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN courses c ON c.id=s.course_id LEFT JOIN sections sec ON sec.id=s.section_id WHERE '.student_scope_sql().' ORDER BY u.full_name') as $s): ?><tr><td><?= e($s['student_no']) ?></td><td><?= e($s['full_name']) ?></td><td><?= e($s['course']) ?></td><td><?= e($s['year_level']) ?></td><td><?= e($s['section_name']) ?></td><td><span class="badge-soft risk-<?= e($s['risk_level']) ?>"><?= e($s['risk_level']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php render_footer(); ?>
